#include <print>
#include <ranges>

int main() {
    auto cube = std::views::iota(1)
              | std::views::transform([](int n) { std::print("[造 {}]", n); return n * n * n; })
              | std::views::take(5);
    std::println("视图建好了，上面一个字都没打印");
    for (int v : cube) std::print("{} ", v);
    std::println("");
    // 不惰性就根本走不完：建立视图那一刻得数完一个没有终点的序列，take 退化成先造完再剪短
    return 0;
}

